from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.orders import OrderSummary


class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._orders = orders
        self._customers = customers

    def _active_summaries(self, customer_id: str) -> list[OrderSummary]:
        """A customer's non-cancelled order summaries, newest first. Raises CustomerNotFound."""
        return [s for s in self._orders.order_history(customer_id) if s.order.status != "cancelled"]

    def _lifetime_value_cents(self, customer_id: str) -> int:
        return sum(s.total_cents for s in self._active_summaries(customer_id))

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the same totals the order summary reports."""
        try:
            summaries = self._orders.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        orders: list[dict[str, Any]] = [
            {"order_id": s.order.order_id, "status": s.order.status, "total_cents": s.total_cents}
            for s in summaries
        ]
        return Response(200, {"customer_id": customer_id, "orders": orders})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Number of non-cancelled orders and the sum of their totals, in cents."""
        try:
            active = self._active_summaries(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "order_count": len(active),
            "lifetime_value_cents": sum(s.total_cents for s in active),
        })

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers with the highest lifetime value (ties broken by customer_id), omitting zeros."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            value = self._lifetime_value_cents(customer.customer_id)
            if value > 0:
                ranked.append((value, customer))
        ranked.sort(key=lambda entry: (-entry[0], entry[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": c.customer_id, "name": c.name, "lifetime_value_cents": value}
            for value, c in ranked[:limit]
        ]})

